package lt.viko.eif.imazolevska.rehearsalbooking.repository;

import lt.viko.eif.imazolevska.rehearsalbooking.entity.Booking;
import lt.viko.eif.imazolevska.rehearsalbooking.entity.BookingStatus;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.List;


/**
 * Repository for reading and saving bookings.
 * The implementation is generated by Spring Data JPA.
 */
public interface BookingRepository extends JpaRepository<Booking, Long> {

    /**
     * Finds all bookings of the given room, both active and canceled.
     *
     * @param roomId the room ID
     * @return the list of bookings, empty if there are none
     */
    List<Booking> findByRoomId(Long roomId);

    /**
     * Finds all bookings of the given band, both active and canceled.
     *
     * @param bandId the band ID
     * @return the list of bookings, empty if there are none
     */
    List<Booking> findByBandId(Long bandId);

    /**
     * Finds bookings of the given room with the given status, sorted by start time.
     *
     * @param roomId the room ID
     * @param status the booking status, for example ACTIVE
     * @return the list of bookings, empty if there are none
     */
    List<Booking> findByRoomIdAndStatusOrderByStartTimeAsc(Long roomId, BookingStatus status);


}
